import{_ as e,a as o,b as r,c as d,d as s}from"./chunks/26-dashboard-player.BKek0GVz.js";import{_ as a,o as n,c,a2 as p}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"لوحة التحكم","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/dashboard.md","filePath":"ar/guide/dashboard.md"}'),g={name:"ar/guide/dashboard.md"};function i(l,t,h,m,_,u){return n(),c("div",null,[...t[0]||(t[0]=[p('<h1 id="لوحة-التحكم" tabindex="-1">لوحة التحكم <a class="header-anchor" href="#لوحة-التحكم" aria-label="Permalink to &quot;لوحة التحكم&quot;">​</a></h1><p>يفتح الأمر <code>reelforge studio</code> (أو <code>start.bat</code> أو <code>start.sh</code>) لوحة التحكم على العنوان <code>http://127.0.0.1:4310</code>. تعرض اللوحة <strong>حلقاتك</strong> (مجلد <code>episodes/</code>) و<strong>الأمثلة</strong>.</p><p><img src="'+e+'" alt="لوحة التحكم"></p><p>تعرض كل بطاقة صورة مصغرة حية، والسلسلة، والـ preset، وعدد الأسطر والمشاهد، والمدة، وشارات الحالة:</p><table tabindex="0"><thead><tr><th>الشارة</th><th>المعنى</th></tr></thead><tbody><tr><td><code>voice 1:15</code> / <code>no voice</code></td><td>هل يوجد تسجيل صوتي، وما مدته</td></tr><tr><td><code>cues 24/24</code> / <code>draft cues</code> / <code>no cues</code></td><td>عدد الجمل التي حُددت بدايتها؛ أما الـ cues التقديرية فمجرد تقدير</td></tr><tr><td><code>valid</code> / <code>2 warnings</code> / <code>1 error</code></td><td>نتيجة الفحوص الثابتة (مرّر المؤشر فوق الخطأ لقراءته)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الزر</th><th>وظيفته</th></tr></thead><tbody><tr><td><strong>Upload voice</strong></td><td>اختر تسجيلاً فيُحوَّل إلى <code>voice.wav</code> ‏(48 kHz)</td></tr><tr><td><strong>Open editor</strong></td><td>يفتح المحرر المرئي للحلقة في تبويب جديد (راجع <a href="./editor.html">المحرر</a>)</td></tr><tr><td><strong>Mark cues</strong></td><td>يفتح المحرر في وضع Cues، جاهزاً لتحديد بداية كل جملة</td></tr><tr><td><strong>Auto cues</strong></td><td>يحاذي كل سطر وكل كلمة مع التسجيل (راجع <a href="./timing.html">التوقيت والـ cues والمحاذاة</a>)</td></tr><tr><td><strong>Validate</strong></td><td>يشغّل كل الفحوص، بما فيها فحصا تجاوز النص لصندوقه وطول الترجمة النصية في متصفح دون واجهة (headless)</td></tr><tr><td><strong>Render</strong></td><td>اختر الـ preset وحجم ملف النشر والمؤثرات والسرعة؛ ويظهر التقدم وعدد الإطارات في الثانية والوقت المتبقي مباشرةً، ويوقف <strong>Cancel</strong> التصدير بأمان</td></tr><tr><td><strong>Folder</strong></td><td>يفتح مجلد الحلقة في مدير الملفات</td></tr><tr><td><strong>Draft cues</strong></td><td>(عند غياب الـ cues فقط) يقدّر التوقيت من طول النص</td></tr></tbody></table><p>للبدء من قالب قطاعي انقر <strong>+ New episode</strong> ثم اختر <strong>Start from template</strong>: اختر حزمة وقالباً، واملأ الحقول واللغة، فتُفتح الحلقة في المحرر (راجع <a href="./templates-and-packs.html">القوالب والحزم</a>).</p><p><img src="'+o+'" alt="نتائج التحقق"></p><p><img src="'+r+'" alt="خيارات التصدير"></p><p><img src="'+d+'" alt="تقدم التصدير المباشر"></p><p>تظهر المخرجات الجاهزة كروابط على البطاقة، وتُفتح الفيديوهات في مشغّل فيه زر <strong>Download</strong>.</p><p><img src="'+s+'" alt="المشغّل المدمج"></p><p>تعرض صفحة <strong>Gallery</strong> ‏(<code>/gallery</code>) كل ما يمكنك استخدامه في حلقاتك. يسرد تبويب <strong>Components</strong> المكونات الـ 62 مصنفةً حسب الفئة، مع مربع بحث وإطار معاينة من معرض المكونات؛ وعند النقر على مكوّن تظهر خصائصه (props) ومقتطف YAML جاهز للنسخ. ويعرض تبويب <strong>Themes</strong> معاينة لكل theme مدمج أو خاص بالمشروع، مبنيةً على ألوانه وخطوطه، مع وضعه (فاتح أو داكن) ونتيجة فحص التباين وفق WCAG. أما تبويب <strong>Packs</strong> فيسرد الحزم القطاعية بالإنجليزية أو العربية، ويفتح الزر <strong>Use this template</strong> نافذة الحلقة الجديدة وقد اختير فيها القالب.</p><p>تقدم صفحة <strong>Connect AI</strong> ‏(<code>/connect</code>) إعدادات جاهزة للنسخ لعملاء الذكاء الاصطناعي؛ راجع <a href="./ai.html">التكامل مع الذكاء الاصطناعي</a>.</p><p>يفتح الزر <strong>Documentation</strong> هذا التوثيق على المسار <code>/docs/</code> من مجلد ReelForge على جهازك، فيعمل دون اتصال. وفيه صفحات الموقع نفسها بالإنجليزية والعربية (بدّل بينهما من قائمة اللغة)، مع البحث.</p><p>لا يعمل إلا تصدير واحد في كل مرة. تستمع لوحة التحكم افتراضياً على <code>127.0.0.1</code>، فلا تصل إليها أجهزة أخرى. ويربطها الخيار <code>--host</code> بعنوان آخر، وعندها تشترط نقاط الوصول (endpoints) الخاصة بالذكاء الاصطناعي token من نوع bearer (راجع <a href="./ai.html#security">الأمان</a>).</p>',16)])])}const v=a(g,[["render",i]]);export{k as __pageData,v as default};
